exec('''"""РЕСУРС: функции для вывода текста, красивого выводаLINESPLITTER - Класс журнала приложения"""LINESPLITTERLINESPLITTERimport sysLINESPLITTERimport inspectLINESPLITTERimport datetimeLINESPLITTERfrom pathlib import PathLINESPLITTERLINESPLITTERLINESPLITTER# -- класс журнала приложенияLINESPLITTERclass Logger:LINESPLITTER    def __init__(self):LINESPLITTER        self._real_stdout = sys.__stdout__LINESPLITTER        self._lines = []LINESPLITTER        sys.stdout = selfLINESPLITTERLINESPLITTER    def write(self, text: str):LINESPLITTER        self._real_stdout.write(text)LINESPLITTER        self._real_stdout.flush()LINESPLITTERLINESPLITTER        self._lines.append(text)LINESPLITTERLINESPLITTER    def flush(self):LINESPLITTER        self._real_stdout.flush()LINESPLITTERLINESPLITTER    def get_log(self) -> str:LINESPLITTER        return "".join(self._lines)LINESPLITTERLINESPLITTER    def clear(self):LINESPLITTER        self._lines.clear()LINESPLITTERLINESPLITTER    def log(self, *args, **kwargs):LINESPLITTER        frame = inspect.stack()[1]LINESPLITTERLINESPLITTER        filename = Path(frame.filename)LINESPLITTER        filename = Path(*filename.parts[-2:])LINESPLITTERLINESPLITTER        lineno = frame.linenoLINESPLITTERLINESPLITTER        timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")LINESPLITTER        message = " ".join(str(x) for x in args)LINESPLITTER        formatted = f"[{timestamp}] {filename}:{lineno} | {message}"LINESPLITTERLINESPLITTER        print(formatted, **kwargs)LINESPLITTERLINESPLITTER    def split_log(self, message=\'\'):LINESPLITTER        print(\'*-\' * 10 + message.upper() + \'-*\' * 10)LINESPLITTER'''.replace('LINESPLITTER', '\n'))